// ─── Write tools ─────────────────────────────────────────────────────────────
// Mutations, each gated on explicit user confirmation.
//
// Every handler here takes a `scope` argument from the transport:
//
//   'preview' — describe exactly what would change, change nothing.
//   'execute' — perform the change.
//
// Splitting the two means the text the user approves is generated by the same
// code path that does the write, so a preview cannot drift from the effect.
//
// Three rules the write path enforces that the read path does not need:
//
//   1. Field allowlists. Assignments are mass-assigned from a fixed set of
//      fields. A model that decides to also send `schoolId`, or `creatorId`, or
//      `isPublished`, simply has those ignored. Without this, "create an exam in
//      my class" could become "create an exam visible to the whole school".
//
//   2. Ownership re-verified in both scopes. Checking only on execute would
//      mean the preview step leaks whether another teacher's class exists;
//      checking only on preview would leave a window to swap the argument
//      between the two calls. The confirmation token's argument hash covers that
//      second case, but re-checking here is cheap and unconditional.
//
//   3. No destructive operations. Nothing here deletes or unpublishes existing
//      records. Removing content is a separate, deliberate, human-initiated
//      action outside the assistant's reach.

const { register, SCOPES } = require('./registry');
const Topic = require('../../models/Topic');
const Assignment = require('../../models/Assignment');
const Exam = require('../../models/Exam');
const Classroom = require('../../models/Classroom');
const { ownClassroomIds, trim } = require('./read');

const STAFF = ['teacher', 'personal_teacher', 'school_admin', 'root_admin'];

const bad = (message, code = 'NOT_FOUND') => {
    const err = new Error(message);
    err.code = code;
    return err;
};

/** Reject anything that is not a plausible ObjectId for our own records. */
const validId = (value) =>
    typeof value === 'string' && /^[a-fA-F0-9]{24}$/.test(value);

/** Confirm a class exists *and* belongs to the caller. */
const assertOwnClass = async (user, classroomId) => {
    if (!validId(classroomId)) throw bad('A valid classId is required.');
    const ids = await ownClassroomIds(user);
    if (!ids.some((id) => String(id) === classroomId)) {
        throw bad('That class is not one of yours.');
    }
    return classroomId;
};

const ownTopic = async (user, topicId) => {
    if (!validId(topicId)) throw bad('A valid topicId is required.');
    const topic = await Topic.findById(topicId).lean();
    if (!topic) throw bad('That topic was not found.');
    await assertOwnClass(user, String(topic.classroomId));
    return topic;
};

const parseDate = (value, field) => {
    if (value === undefined || value === null || value === '') return null;
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) {
        throw bad(`"${field}" is not a valid date.`, 'INVALID_INPUT');
    }
    return date;
};

/**
 * Copy only whitelisted string fields off a model-generated object.
 * Anything unrecognised is dropped rather than rejected, so an extra key from a
 * model costs the user nothing.
 */
const pick = (source, fields) => {
    const out = {};
    for (const [key, maxLength] of Object.entries(fields)) {
        const value = source?.[key];
        if (typeof value === 'string' && value.trim()) {
            out[key] = value.trim().slice(0, maxLength);
        }
    }
    return out;
};

/**
 * Convert drafted questions into stored questions.
 *
 * Drafts arrive as prose answers, but the schema stores either theory questions
 * or multiple-choice ones with a `correctOption`. Rather than inventing options
 * the teacher never wrote, an item becomes MCQ only when real options were
 * supplied; otherwise it stays theory and the model answer goes into the
 * description. Anything dropped is reported so the user sees it before
 * approving, not after.
 */
const buildQuestions = (rawQuestions, { defaultMarks }) => {
    if (!Array.isArray(rawQuestions)) return { questions: [], notes: ['No questions were supplied.'] };

    const notes = [];
    const questions = [];
    let mcqCount = 0;

    rawQuestions.slice(0, 100).forEach((raw, index) => {
        if (!raw || typeof raw !== 'object') return;

        const text = typeof raw.question === 'string' ? raw.question.trim() : '';
        if (!text) return;

        const marks = Number.isFinite(Number(raw.marks)) && Number(raw.marks) > 0
            ? Math.min(Number(raw.marks), 1000)
            : defaultMarks;

        const options = Array.isArray(raw.options)
            ? raw.options.filter((o) => typeof o === 'string' && o.trim()).map((o) => o.trim().slice(0, 500))
            : [];
        const answer = typeof raw.modelAnswer === 'string' ? raw.modelAnswer.trim().slice(0, 2000) : '';

        if (options.length >= 2) {
            mcqCount += 1;
            questions.push({
                questionText: text.slice(0, 2000),
                questionType: 'mcq',
                options,
                correctOption: answer || options[0],
                maxScore: marks,
            });
            return;
        }

        // Theory question: keep the model answer with the question so a teacher
        // can see the reasoning, but flag it as needing review.
        if (answer) {
            notes.push(`Question ${index + 1}: the drafted answer is stored alongside the question and should be checked before release.`);
        }
        questions.push({
            questionText: answer ? `${text}\n\n[Drafted answer, needs review: ${answer}]` : text,
            maxScore: marks,
        });
    });

    if (mcqCount && mcqCount !== questions.length) {
        notes.push('Questions are mixed multiple-choice and written answer; the stored type differs per question.');
    }
    return { questions, notes };
};

const totalOf = (questions) =>
    questions.reduce((sum, q) => sum + (q.maxScore || 0), 0);

// ─── Topics ──────────────────────────────────────────────────────────────────

const TOPIC_FIELDS = {
    name: 200,
    description: 5000,
    lessonsOutline: 100000,
};

register({
    name: 'create_topic',
    description: 'Create a new lesson topic in one of your classes. Requires user confirmation.',
    effect: 'write',
    requiredScope: SCOPES.WRITE,
    allowedRoles: STAFF,
    inputSchema: {
        type: 'object',
        properties: {
            classroomId: { type: 'string' },
            name: { type: 'string', description: 'Topic title.' },
            description: { type: 'string', description: 'Short summary.' },
            lessonsOutline: { type: 'string', description: 'The lesson outline or full content.' },
            order: { type: 'number', description: 'Position in the class.' },
        },
        required: ['classroomId', 'name'],
        additionalProperties: false,
    },
    handler: async ({ user, args, scope }) => {
        await assertOwnClass(user, args.classroomId);
        const fields = pick(args, TOPIC_FIELDS);
        if (!fields.name) throw bad('"name" is required.', 'INVALID_INPUT');
        const order = Number.isFinite(Number(args.order)) ? Number(args.order) : 0;

        if (scope === 'preview') {
            return {
                action: 'Create topic',
                inClass: args.classroomId,
                name: fields.name,
                description: fields.description || '(none)',
                hasOutline: Boolean(fields.lessonsOutline),
                order,
            };
        }

        const topic = await Topic.create({
            name: fields.name,
            description: fields.description,
            lessonsOutline: fields.lessonsOutline,
            classroomId: args.classroomId,
            order,
            status: 'pending',
        });

        return { created: true, topicId: String(topic._id), name: topic.name };
    },
});

register({
    name: 'update_topic',
    description:
        'Update the title, summary or outline of one of your topics. Only these fields can change. Requires user confirmation.',
    effect: 'write',
    requiredScope: SCOPES.WRITE,
    allowedRoles: STAFF,
    inputSchema: {
        type: 'object',
        properties: {
            topicId: { type: 'string' },
            name: { type: 'string' },
            description: { type: 'string' },
            lessonsOutline: { type: 'string' },
        },
        required: ['topicId'],
        additionalProperties: false,
    },
    handler: async ({ user, args, scope }) => {
        const topic = await ownTopic(user, args.topicId);
        const fields = pick(args, TOPIC_FIELDS);

        const changed = Object.entries(fields).filter(([key, value]) => (topic[key] || '') !== value);
        if (!changed.length) {
            throw bad('That would not change anything — the values already match.', 'NO_OP');
        }

        if (scope === 'preview') {
            return {
                action: 'Update topic',
                topicId: String(topic._id),
                topic: topic.name,
                changes: changed.map(([field, value]) => ({
                    field,
                    from: trim(topic[field], 200) || '(empty)',
                    to: trim(value, 200) || '(empty)',
                })),
            };
        }

        await Topic.updateOne({ _id: topic._id }, { $set: fields });
        return { updated: true, topicId: String(topic._id), fields: Object.keys(fields) };
    },
});

// ─── Assignments ─────────────────────────────────────────────────────────────

register({
    name: 'create_assignment',
    description:
        'Save an assignment with its questions into one of your classes. Requires user confirmation.',
    effect: 'write',
    requiredScope: SCOPES.WRITE,
    allowedRoles: STAFF,
    inputSchema: {
        type: 'object',
        properties: {
            classroomId: { type: 'string' },
            topicId: { type: 'string', description: 'Optional: link to a topic.' },
            title: { type: 'string' },
            description: { type: 'string' },
            dueDate: { type: 'string', description: 'ISO date.' },
            assignmentType: { type: 'string', enum: ['mcq', 'theory'] },
            maxScore: { type: 'number' },
            questions: {
                type: 'array',
                description: 'Questions in the shape returned by draft_assignment.',
                items: {
                    type: 'object',
                    properties: {
                        question: { type: 'string' },
                        marks: { type: 'number' },
                        options: { type: 'array', items: { type: 'string' } },
                        modelAnswer: { type: 'string' },
                    },
                    required: ['question'],
                },
            },
            published: { type: 'boolean', description: 'Visible to students immediately (default false).' },
        },
        required: ['classroomId', 'title'],
        additionalProperties: false,
    },
    handler: async ({ user, args, scope }) => {
        await assertOwnClass(user, args.classroomId);
        const title = pick(args, { title: 200 }).title;
        if (!title) throw bad('"title" is required.', 'INVALID_INPUT');

        const description = pick(args, { description: 20000 }).description || '';
        const dueDate = parseDate(args.dueDate, 'dueDate');
        const { questions, notes } = buildQuestions(args.questions, {
            defaultMarks: Number(args.maxScore) || 100,
        });

        // Default to unpublished: an AI-drafted assignment appearing in every
        // student's feed without the teacher looking at it is not a good default.
        const published = args.published === true;

        if (scope === 'preview') {
            return {
                action: 'Create assignment',
                inClass: args.classroomId,
                title,
                questionCount: questions.length,
                totalMarks: questions.length ? totalOf(questions) : Number(args.maxScore) || 100,
                dueDate: dueDate ? dueDate.toISOString() : 'none',
                visibleToStudents: published,
                notes: notes.length ? notes : [],
            };
        }

        let topicId = null;
        if (args.topicId && validId(args.topicId)) {
            const topic = await ownTopic(user, args.topicId);
            topicId = topic._id;
        }

        const assignment = await Assignment.create({
            title,
            description,
            classroomId: args.classroomId,
            topicId,
            dueDate,
            maxScore: questions.length ? totalOf(questions) : Number(args.maxScore) || 100,
            assignmentType: args.assignmentType === 'mcq' ? 'mcq' : 'theory',
            questions,
            published,
        });

        return {
            created: true,
            assignmentId: String(assignment._id),
            title,
            questionCount: questions.length,
            notes: notes.length ? notes : [],
        };
    },
});

register({
    name: 'set_assignment_published',
    description: 'Show or hide an existing assignment from students. Requires user confirmation.',
    effect: 'write',
    requiredScope: SCOPES.WRITE,
    allowedRoles: STAFF,
    inputSchema: {
        type: 'object',
        properties: {
            assignmentId: { type: 'string' },
            published: { type: 'boolean' },
        },
        required: ['assignmentId', 'published'],
        additionalProperties: false,
    },
    handler: async ({ user, args, scope }) => {
        if (!validId(args.assignmentId)) throw bad('A valid assignmentId is required.');

        const assignment = await Assignment.findById(args.assignmentId).lean();
        if (!assignment) throw bad('That assignment was not found.');
        await assertOwnClass(user, String(assignment.classroomId));

        const published = args.published === true;
        if (Boolean(assignment.published) === published) {
            throw bad(`That assignment is already ${published ? 'published' : 'hidden'}.`, 'NO_OP');
        }

        if (scope === 'preview') {
            return {
                action: published ? 'Publish assignment' : 'Hide assignment',
                assignmentId: String(assignment._id),
                title: assignment.title,
                from: assignment.published ? 'visible to students' : 'hidden',
                to: published ? 'visible to students' : 'hidden',
            };
        }

        await Assignment.updateOne({ _id: assignment._id }, { $set: { published } });
        return { updated: true, assignmentId: String(assignment._id), published };
    },
});

// ─── Exams ───────────────────────────────────────────────────────────────────

register({
    name: 'create_exam',
    description:
        'Save an exam paper into one of your classes. Exams start unpublished, so nothing is visible to students until you publish it. Requires user confirmation.',
    effect: 'write',
    requiredScope: SCOPES.WRITE,
    allowedRoles: STAFF,
    inputSchema: {
        type: 'object',
        properties: {
            classroomId: { type: 'string' },
            title: { type: 'string' },
            description: { type: 'string' },
            duration: { type: 'number', description: 'Time limit in minutes.' },
            dueDate: { type: 'string', description: 'ISO date.' },
            accessMode: { type: 'string', enum: ['registered', 'open'] },
            questions: {
                type: 'array',
                description: 'Questions in the shape returned by draft_exam.',
                items: {
                    type: 'object',
                    properties: {
                        question: { type: 'string' },
                        marks: { type: 'number' },
                        options: { type: 'array', items: { type: 'string' } },
                        modelAnswer: { type: 'string' },
                    },
                    required: ['question'],
                },
            },
        },
        required: ['classroomId', 'title', 'duration'],
        additionalProperties: false,
    },
    handler: async ({ user, args, scope }) => {
        await assertOwnClass(user, args.classroomId);
        const title = pick(args, { title: 200 }).title;
        if (!title) throw bad('"title" is required.', 'INVALID_INPUT');

        const duration = Number(args.duration);
        if (!Number.isFinite(duration) || duration <= 0 || duration > 600) {
            throw bad('"duration" must be between 1 and 600 minutes.', 'INVALID_INPUT');
        }

        const description = pick(args, { description: 20000 }).description || '';
        const dueDate = parseDate(args.dueDate, 'dueDate');
        const { questions, notes } = buildQuestions(args.questions, { defaultMarks: 10 });
        const accessMode = args.accessMode === 'open' ? 'open' : 'registered';

        if (scope === 'preview') {
            return {
                action: 'Create exam',
                inClass: args.classroomId,
                title,
                questionCount: questions.length,
                totalMarks: questions.length ? totalOf(questions) : 0,
                durationMinutes: duration,
                accessMode,
                dueDate: dueDate ? dueDate.toISOString() : 'none',
                visibleToStudents: false,
                notes: notes.length ? notes : [],
            };
        }

        const classroom = await Classroom.findById(args.classroomId).select('schoolId').lean();
        // Both of these are arrays on their own schema (Classroom.schoolId and
        // User.schoolId) while Exam.schoolId is a single ref, so the first entry
        // is taken rather than the array.
        const schoolId = classroom?.schoolId?.[0] || user.schoolId?.[0] || null;

        const exam = await Exam.create({
            title,
            description,
            creatorId: user._id,
            classId: args.classroomId,
            schoolId,
            duration,
            dueDate,
            accessMode,
            questions,
            isPublished: false,
            resultsPublished: false,
        });

        return {
            created: true,
            examId: String(exam._id),
            title,
            questionCount: questions.length,
            published: false,
            notes: notes.length ? notes : [],
        };
    },
});

register({
    name: 'publish_exam',
    description:
        'Make a saved exam available to students in its class. Requires user confirmation.',
    effect: 'write',
    requiredScope: SCOPES.WRITE,
    allowedRoles: STAFF,
    inputSchema: {
        type: 'object',
        properties: {
            examId: { type: 'string' },
            startTime: { type: 'string', description: 'Optional ISO datetime to open the exam at.' },
            dueDate: { type: 'string', description: 'Optional ISO datetime to close the exam at.' },
        },
        required: ['examId'],
        additionalProperties: false,
    },
    handler: async ({ user, args, scope }) => {
        if (!validId(args.examId)) throw bad('A valid examId is required.');

        const exam = await Exam.findById(args.examId).lean();
        if (!exam) throw bad('That exam was not found.');
        await assertOwnClass(user, String(exam.classId));

        if (exam.isPublished) {
            throw bad('That exam is already published.', 'NO_OP');
        }

        const startTime = parseDate(args.startTime, 'startTime');
        const dueDate = parseDate(args.dueDate, 'dueDate');
        if (startTime && dueDate && startTime.getTime() >= dueDate.getTime()) {
            throw bad('The closing time must be after the opening time.', 'INVALID_INPUT');
        }

        if (scope === 'preview') {
            return {
                action: 'Publish exam',
                examId: String(exam._id),
                title: exam.title,
                questions: Array.isArray(exam.questions) ? exam.questions.length : 0,
                durationMinutes: exam.duration,
                accessMode: exam.accessMode,
                opensAt: startTime ? startTime.toISOString() : 'immediately',
                closesAt: dueDate ? dueDate.toISOString() : 'no closing time set',
            };
        }

        const update = { isPublished: true };
        if (startTime) update.startTime = startTime;
        if (dueDate) update.dueDate = dueDate;

        await Exam.updateOne({ _id: exam._id }, { $set: update });
        return { published: true, examId: String(exam._id), title: exam.title };
    },
});
